//! Documentation embedded into the binary and served by the `bialet_docs` tool.
//!
//! The complete Bialet documentation tree (vendored under
//! `assets/bialet-docs/`) plus the curated Wren references in `assets/docs/`
//! are compiled into the binary. The manifest is generated by `build.rs` from
//! the files on disk, so adding a page never requires touching Rust code.
//!
//! `bialet_docs` looks pages up by name (relative path or basename); local
//! docs passed through `ToolContext::docs_dir` still take precedence.

/// One bundled page: the doc's file name and its full contents.
#[derive(Clone, Copy, Debug)]
pub struct EmbeddedDoc {
    pub name: &'static str,
    pub content: &'static str,
}

include!(concat!(env!("OUT_DIR"), "/embedded_docs_generated.rs"));

/// Look up a bundled page by its relative name, basename or case-insensitive
/// spelling. Returns `None` when no page matches.
pub fn get(name: &str) -> Option<&'static EmbeddedDoc> {
    let name = name.trim().trim_start_matches("./").trim_start_matches('/');
    if name.is_empty() {
        return None;
    }

    if let Some(doc) = exact(name) {
        return Some(doc);
    }
    for ext in ["md", "rst", "wren"] {
        if let Some(doc) = exact(&format!("{name}.{ext}")) {
            return Some(doc);
        }
    }

    // Basenames are unambiguous in practice (`datetime.md`, `reference.md`),
    // and the model often passes just the file name it saw in a link.
    let base = name.rsplit('/').next().unwrap_or(name);
    let mut matches = EMBEDDED_DOCS
        .iter()
        .filter(|d| d.name.rsplit('/').next() == Some(base));
    let first = matches.next()?;
    if matches.next().is_some() {
        return None;
    }
    Some(first)
}

fn exact(name: &str) -> Option<&'static EmbeddedDoc> {
    EMBEDDED_DOCS.iter().find(|d| d.name == name).or_else(|| {
        EMBEDDED_DOCS
            .iter()
            .find(|d| d.name.eq_ignore_ascii_case(name))
    })
}

/// Every page name, sorted as compiled (upstream first, then curated).
pub fn names() -> impl Iterator<Item = &'static str> {
    EMBEDDED_DOCS.iter().map(|d| d.name)
}

/// Pages whose heading mentions `needle`, used to turn a dead end such as
/// `file=date-reference` into a useful pointer.
pub fn pages_with_heading(needle: &str, limit: usize) -> Vec<(&'static str, String)> {
    let needle = needle.to_lowercase();
    if needle.is_empty() {
        return Vec::new();
    }
    let mut out = Vec::new();
    for doc in EMBEDDED_DOCS {
        for line in doc.content.lines() {
            let Some(title) = line.strip_prefix('#') else {
                continue;
            };
            let title = title.trim().trim_start_matches('#').trim();
            if title.to_lowercase().contains(&needle) {
                out.push((doc.name, title.to_string()));
                break;
            }
        }
        if out.len() >= limit {
            break;
        }
    }
    out
}

/// Names that contain `needle`, for "did you mean" suggestions.
pub fn similar_names(needle: &str, limit: usize) -> Vec<&'static str> {
    let needle = needle.to_lowercase();
    names()
        .filter(|n| n.to_lowercase().contains(&needle))
        .take(limit)
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::path::{Path, PathBuf};

    fn assets() -> PathBuf {
        Path::new(env!("CARGO_MANIFEST_DIR")).join("../../assets")
    }

    fn walk(dir: &Path, root: &Path, out: &mut Vec<String>) {
        let Ok(entries) = std::fs::read_dir(dir) else {
            return;
        };
        for entry in entries.filter_map(Result::ok) {
            let path = entry.path();
            if path.is_dir() {
                walk(&path, root, out);
            } else if matches!(
                path.extension().and_then(|e| e.to_str()),
                Some("md" | "rst" | "wren")
            ) {
                let relative = path.strip_prefix(root).expect("walked path is under root");
                out.push(
                    relative
                        .components()
                        .map(|c| c.as_os_str().to_string_lossy().into_owned())
                        .collect::<Vec<_>>()
                        .join("/"),
                );
            }
        }
    }

    #[test]
    fn every_vendored_doc_is_embedded() {
        let upstream = assets().join("bialet-docs");
        let mut pages = Vec::new();
        walk(&upstream, &upstream, &mut pages);
        assert!(!pages.is_empty(), "assets/bialet-docs is empty");
        for page in &pages {
            let doc = get(page).unwrap_or_else(|| panic!("{page} is not embedded"));
            assert!(!doc.content.trim().is_empty(), "{page} has no content");
        }
        // The full documentation tree is large; a handful of pages means the
        // sync silently regressed to the old curated subset.
        assert!(
            pages.len() >= 40,
            "only {} page(s) vendored; run scripts/sync-bialet-docs.sh",
            pages.len()
        );
    }

    #[test]
    fn curated_wren_references_are_embedded() {
        for name in [
            "wren-num.md",
            "wren-string.md",
            "wren-list.md",
            "bialet-recipes.md",
            "bialet-pitfalls.md",
        ] {
            let doc = get(name).unwrap_or_else(|| panic!("{name} is not embedded"));
            assert!(doc.content.contains('#'), "{name} has no heading");
        }
    }

    #[test]
    fn key_bialet_pages_are_reachable_by_basename() {
        for name in [
            "datetime.md",
            "reference.md",
            "usage.md",
            "deployment.md",
            "security.md",
            "forms.md",
            "file.md",
            "http-calls.md",
            "configuration.md",
            "errors.md",
            "getting-started/1-introduction.md",
        ] {
            let doc = get(name).unwrap_or_else(|| panic!("{name} is not reachable"));
            assert!(doc.content.contains('#'), "{name} has no heading");
            // Basename lookup must resolve too: the model often passes the
            // file name alone after following an in-doc link.
            let base = name.rsplit('/').next().unwrap();
            assert!(get(base).is_some(), "{base} is not reachable by basename");
        }
    }

    #[test]
    fn markdown_links_between_docs_resolve() {
        for doc in EMBEDDED_DOCS {
            let dir = match doc.name.rfind('/') {
                Some(i) => &doc.name[..i],
                None => "",
            };
            for link in markdown_file_links(doc.content) {
                if link.starts_with("http://") || link.starts_with("https://") {
                    continue;
                }
                let target = link.split('#').next().unwrap_or(&link);
                if !target.ends_with(".md") && !target.ends_with(".rst") {
                    continue;
                }
                let resolved = normalize(dir, target);
                assert!(
                    get(&resolved).is_some(),
                    "{} links to {} but that page is not embedded",
                    doc.name,
                    link
                );
            }
        }
    }

    #[test]
    fn the_prompt_only_links_bundled_pages() {
        let prompt = std::fs::read_to_string(assets().join("bialet_prompt.md"))
            .expect("the bundled Bialet guide exists");
        for link in markdown_file_links(&prompt) {
            if link.ends_with(".md") || link.ends_with(".rst") {
                assert!(
                    get(&link).is_some(),
                    "the prompt links to {link} but that page is not bundled"
                );
            }
        }
    }

    #[test]
    fn headings_help_a_dead_end_lookup() {
        let pages = pages_with_heading("date", 5);
        assert!(
            pages
                .iter()
                .any(|(name, _)| *name == "reference.md" || *name == "datetime.md"),
            "expected a Date page in {pages:?}"
        );
        assert!(similar_names("datetime", 5).contains(&"datetime.md"));
    }

    /// Extract `](target)` targets from Markdown; anchors and titles ignored.
    fn markdown_file_links(content: &str) -> Vec<String> {
        let mut out = Vec::new();
        let mut rest = content;
        while let Some(start) = rest.find("](") {
            rest = &rest[start + 2..];
            let Some(end) = rest.find(')') else {
                break;
            };
            let target = rest[..end].trim().trim_matches('<').trim_matches('>');
            let target = target.split_whitespace().next().unwrap_or(target);
            if !target.is_empty() {
                out.push(target.to_string());
            }
            rest = &rest[end + 1..];
        }
        out
    }

    /// Resolve `../database.md` relative to the directory holding the page.
    fn normalize(dir: &str, target: &str) -> String {
        let mut parts: Vec<&str> = if target.starts_with('/') {
            Vec::new()
        } else {
            dir.split('/').filter(|s| !s.is_empty()).collect()
        };
        for part in target.trim_start_matches('/').split('/') {
            match part {
                "" | "." => {}
                ".." => {
                    parts.pop();
                }
                other => parts.push(other),
            }
        }
        parts.join("/")
    }
}
